namespace sv_8e943a3f99584bbbafc27423886a7218.Components.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (per-circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#6366f1";

    public ThemeMode Theme => _theme;
    public string AccentColor => _accentColor;

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (_theme == theme) return;
        _theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_accentColor == color) return;
        _accentColor = color;
        OnChange?.Invoke();
    }
}

@using sv_8e943a3f99584bbbafc27423886a7218.Components.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<div class="theme-indicator">
    Theme: <strong>@ThemeService.Theme</strong> | Accent: <span style="color:@ThemeService.AccentColor;">●</span>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        await ApplyThemeToDocument();
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDocument();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        try
        {
            await JS.InvokeVoidAsync("applyTheme",
                ThemeService.Theme.ToString().ToLowerInvariant(),
                ThemeService.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@using sv_8e943a3f99584bbbafc27423886a7218.Components.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<h3>User Preferences</h3>

<div class="mb-3">
    <label>Theme:</label>
    <select @bind="selectedTheme" @bind:after="OnThemeChanged">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label>Accent Color:</label>
    <input type="color" @bind="accentColor" @bind:after="OnAccentChanged" />
</div>

<p>Current: <strong>@ThemeService.Theme</strong> / <span style="color:@ThemeService.AccentColor;">@ThemeService.AccentColor</span></p>

@code {
    private ThemeMode selectedTheme;
    private string accentColor = "#6366f1";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.Theme;
        accentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleExternalChange;
    }

    private void OnThemeChanged() => ThemeService.SetTheme(selectedTheme);
    private void OnAccentChanged() => ThemeService.SetAccentColor(accentColor);

    private void HandleExternalChange()
    {
        InvokeAsync(() =>
        {
            selectedTheme = ThemeService.Theme;
            accentColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleExternalChange;
    }
}

window.applyTheme = function (mode, accentColor) {
    const root = document.documentElement;
    root.setAttribute('data-theme', mode);
    root.style.setProperty('--accent-color', accentColor);
};

